const files = ["app/api/briefs/route.ts","app/api/briefs/[id]/founder/route.ts","app/api/runs/route.ts","app/api/runs/[id]/retest/route.ts"];
const block = /  if \(result\.error === "rate_limited"\) \{\n    const seconds = [\s\S]*?\n    \);\n  \}\n/;
for (const f of files) {
  let s = fs.readFileSync(f, "utf8");
  const nl = s.includes("\r\n");
  s = s.replace(/\r\n/g, "\n");
  s = s.replace("const MAX_QUEUED = 20;\n", "").replace("const MAX_RUNS_PER_HOUR = 5;\n", "");
  if (!block.test(s)) throw f + " block";
  s = s.replace(block, '  if (result.error === "rate_limited") return rateLimited(perHour, result.retry_after_seconds);\n');
  if (!s.includes("p_max_per_hour: MAX_RUNS_PER_HOUR")) throw f + " per";
  s = s.replace("p_max_per_hour: MAX_RUNS_PER_HOUR", "p_max_per_hour: perHour");
  const rpc = /\n(  const \{ data(?:: queued)?, error(?:: rpcError)? \} = await (?:supabase\(\)|db)\.rpc\("enqueue_)/;
  if (!rpc.test(s)) throw f + " rpc";
  s = s.replace(rpc, "\n  const perHour = runsPerHour();\n$1");
  s = s.replace('import { clientIp, hashIp } from "@/lib/visitor";', 'import { MAX_QUEUED, rateLimited, runsPerHour } from "@/lib/run-limits";\nimport { clientIp, hashIp } from "@/lib/visitor";');
  if (!s.includes("run-limits")) throw f + " import";
  if (nl) s = s.replace(/\n/g, "\r\n");
  fs.writeFileSync(f, s);
}
