25	export function BriefView({ id }: { id: string }) {
26	  const [state, setState] = useState<State>({ kind: "loading" });
27	  const [connectionTrouble, setConnectionTrouble] = useState(false);
28	
29	  useEffect(() => {
30	    let cancelled = false;
31	    let timer: ReturnType<typeof setTimeout> | undefined;
32	
33	    async function poll() {
34	      try {
35	        const response = await fetch(`/api/briefs/${encodeURIComponent(id)}`, { cache: "no-store" });
36	        if (cancelled) return;
37	        if (response.status === 404) {
38	          setState({ kind: "not_found" });
39	          return;
40	        }
41	        if (!response.ok) throw new Error(`HTTP ${response.status}`);
42	        const { run } = (await response.json()) as { run: BriefRun };
43	        if (cancelled) return;
44	        setState({ kind: "ready", run });
45	        setConnectionTrouble(false);
46	        if (run.status === "done" || run.status === "failed") return;
47	      } catch {
48	        if (cancelled) return;
49	        setConnectionTrouble(true);
50	      }
51	      timer = setTimeout(poll, POLL_MS);
52	    }
53	
54	    poll();
55	    return () => {
56	      cancelled = true;
57	      clearTimeout(timer);
58	    };
59	  }, [id]);
60	
61	  if (state.kind === "loading") {
62	    return (
63	      <main className="fu-page gap-4">
64	        <p role="status" className="m-0 font-code text-[13px] text-ink3">
