  business_model: { label: "inferred"; model: string; evidence: { quote: string; source_url: string }[] };
  claims: BriefClaim[];
  unknowns: string[];
  suggested_journeys: SuggestedJourney[];
  pages: { url: string; kind: string; title: string; method: "http" | "browser"; status: number; bytes: number }[];
  skipped: { url: string; kind: string; reason: string }[];
  limits: { seconds: number; browser_reads: number; stopped: string | null };
  hidden_text?: HiddenTextNote | null;
};

// A site that could not be read: the run is "failed" and the brief says why, in words for the visitor.
export type BriefFailure = { status: "could_not_read"; message: string };

export type BriefRun = {
  id: string;
  url: string;
  status: "queued" | "running" | "done" | "failed";
  brief: Brief | BriefFailure | null;
  cost_usd: number | string | null;
  created_at: string;
  started_at: string | null;
  finished_at: string | null;
};

// One string literal, so supabase-js can infer the row type from it.
export const BRIEF_COLUMNS = "id, url, status, brief, cost_usd, created_at, started_at, finished_at";
import { UUID } from "@/lib/brief-logic";
import { BRIEF_COLUMNS } from "@/lib/brief-types";
import { supabase } from "@/lib/supabase";

const NO_STORE = { "Cache-Control": "no-store" };

function fail(status: number, error: string, message: string) {
  return Response.json({ error, message }, { status, headers: NO_STORE });
}

export async function GET(_request: Request, ctx: RouteContext<"/api/briefs/[id]">) {
  const { id } = await ctx.params;
  if (!UUID.test(id)) return fail(404, "not_found", "We couldn't find that brief.");

  // Only an understand run is a brief; the visitor's IP hash and the raw worker error stay private.
  const { data, error } = await supabase()
    .from("runs")
    .select(BRIEF_COLUMNS)
    .eq("id", id)
    .eq("kind", "understand")
    .maybeSingle();
  if (error) {
    console.error("Reading brief failed:", error.message);
    return fail(500, "server_error", "Something went wrong on our side. Retrying shortly.");
  }
  if (!data) return fail(404, "not_found", "We couldn't find that brief.");
  return Response.json({ run: data }, { headers: NO_STORE });
}
// What a run was started with (address and goal), remembered in this browser tab for the moment between
// starting it and its first response, so the waiting page can show them at once. Presentation only: nothing is
// sent anywhere, and storage that is missing or throws just means the page waits for the server.

export type PendingRun = { url: string; goal: string };

function key(id: string): string {
  return `fu-run:${id}`;
}

export function rememberPendingRun(id: string, run: PendingRun): void {
  try {
    sessionStorage.setItem(key(id), JSON.stringify({ url: run.url, goal: run.goal }));
  } catch {
    // The waiting page shows the address once the server answers.
  }
}

// The raw stored string (a stable snapshot for useSyncExternalStore), or null.
export function pendingRunSnapshot(id: string): string | null {
  try {
    return sessionStorage.getItem(key(id));
  } catch {
    return null;
  }
}

export function parsePendingRun(raw: string | null): PendingRun | null {
  if (!raw) return null;
  try {
    const value = JSON.parse(raw) as Partial<PendingRun>;
    return typeof value.url === "string" && typeof value.goal === "string" ? { url: value.url, goal: value.goal } : null;
  } catch {
    return null;
  }
}
