// The test form's draft (goal, success condition and the chosen way in), kept in this browser tab so a reload
// doesn't lose it. Never the test login, nor the start link (it can carry a guest token). Storage that is
// missing or throws just means no draft.

import type { AccessMode } from "./types.ts";

export type TestDraft = { goal: string; success: string; access: AccessMode };

const KEY = "fu-test-draft";
const ACCESS: AccessMode[] = ["public", "link", "account", "signup"];

export function parseDraft(raw: string | null): TestDraft | null {
  if (!raw) return null;
  try {
    const value = JSON.parse(raw) as Partial<TestDraft>;
    return {
      goal: typeof value.goal === "string" ? value.goal.slice(0, 500) : "",
      success: typeof value.success === "string" ? value.success.slice(0, 300) : "",
      access: ACCESS.includes(value.access as AccessMode) ? (value.access as AccessMode) : "public",
    };
  } catch {
    return null;
  }
}

export function readDraft(): TestDraft | null {
  try {
    return parseDraft(sessionStorage.getItem(KEY));
  } catch {
    return null;
  }
}

export function saveDraft(draft: TestDraft): void {
  try {
    if (!draft.goal && !draft.success && draft.access === "public") sessionStorage.removeItem(KEY);
    else sessionStorage.setItem(KEY, JSON.stringify({ goal: draft.goal, success: draft.success, access: draft.access }));
  } catch {
    // Without storage the draft lasts until the page is reloaded.
  }
}

export function clearDraft(): void {
  try {
    sessionStorage.removeItem(KEY);
  } catch {
    // Nothing to clear.
  }
}
// Paste and blur handlers for the address fields that show a fixed "https://" in front (lib/url-input.ts).
// A paste that needs no cleaning is left to the browser, so its undo still works.

import type { ClipboardEvent, FocusEvent } from "react";

import { cleanUrlInput, valueAfterPaste } from "@/lib/url-input";

export function urlFieldHandlers(set: (value: string, input: HTMLInputElement) => void) {
  return {
    onPaste(event: ClipboardEvent<HTMLInputElement>) {
      const input = event.currentTarget;
      const pasted = event.clipboardData.getData("text");
      const start = input.selectionStart ?? input.value.length;
      const end = input.selectionEnd ?? start;
      const cleaned = valueAfterPaste(input.value, pasted, start, end);
      if (cleaned === input.value.slice(0, start) + pasted + input.value.slice(end)) return;
      event.preventDefault();
      set(cleaned, input);
    },
    onBlur(event: FocusEvent<HTMLInputElement>) {
      const input = event.currentTarget;
      const cleaned = cleanUrlInput(input.value);
      if (cleaned !== input.value) set(cleaned, input);
    },
  };
}
// The address fields show a fixed "https://" in front, so a pasted or typed full address would read
// "https://https://…". On paste and on blur the field keeps only what comes after the protocol: spaces around it
// and a leading http:// or https:// are dropped, and a "www." straight after that protocol too. A "www." typed
// without a protocol is left alone, and nothing else is ever changed.

const PROTOCOL = /^https?:\/\//i;

export function cleanUrlInput(value: string): string {
  const trimmed = value.trim();
  const protocol = trimmed.match(PROTOCOL);
  if (!protocol) return trimmed;
  return trimmed.slice(protocol[0].length).replace(/^www\./i, "");
}

// The field's value after a paste: the pasted text replaces the selection (or goes in at the caret), then the
// whole value is cleaned. A missing selection (some input types have none) appends at the end.
export function valueAfterPaste(current: string, pasted: string, start: number | null, end: number | null): string {
  const from = start ?? current.length;
  const to = end ?? from;
  return cleanUrlInput(current.slice(0, from) + pasted + current.slice(to));
}

