// Drives Chrome over CDP through: Understand submit -> brief waiting -> real brief -> "Test this journey" ->
// prefilled form in view -> test submit -> run waiting. POST /api/briefs, POST /api/runs and the polls for the
// new ids are answered here, so no real run is created. Usage: node check-flow.mjs <outDir>
import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const OUT = process.argv[2];
const BASE = "http://localhost:3123";
const REAL_BRIEF = "8ca3896f-a3d8-475f-b810-5c9b6b98bb9e";
const FAKE_BRIEF = "11111111-2222-4333-8444-555555555555";
const FAKE_RUN = "66666666-7777-4888-9999-aaaaaaaaaaaa";
const CHROME = "C:/Program Files/Google/Chrome/Application/chrome.exe";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const profile = path.join(OUT, "profile");
const chrome = spawn(CHROME, ["--headless=new", "--remote-debugging-port=9333", `--user-data-dir=${profile}`, "--no-first-run", "about:blank"], { stdio: "ignore" });
let wsUrl;
for (let i = 0; i < 50 && !wsUrl; i++) {
  await sleep(200);
  try {
    const list = await (await fetch("http://127.0.0.1:9333/json")).json();
    wsUrl = list.find((t) => t.type === "page")?.webSocketDebuggerUrl;
  } catch {}
}
const ws = new WebSocket(wsUrl);
await new Promise((r) => ws.addEventListener("open", r));
let nextId = 1;
const waiting = new Map();
const handlers = [];
ws.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && waiting.has(msg.id)) {
    waiting.get(msg.id)(msg);
    waiting.delete(msg.id);
  } else if (msg.method) handlers.forEach((h) => h(msg));
});
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = nextId++;
    waiting.set(id, (msg) => (msg.error ? reject(new Error(`${method}: ${msg.error.message}`)) : resolve(msg.result)));
    ws.send(JSON.stringify({ id, method, params }));
  });
const evaluate = async (expression) => {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description ?? "eval failed");
  return r.result.value;
};
const shot = async (name) => {
  const { data } = await send("Page.captureScreenshot", { format: "png" });
  fs.writeFileSync(path.join(OUT, `${name}.png`), Buffer.from(data, "base64"));
};
const waitFor = async (expression, ms = 15000) => {
  const start = Date.now();
  while (Date.now() - start < ms) {
    if (await evaluate(expression).catch(() => false)) return Date.now() - start;
    await sleep(50);
  }
  throw new Error(`timed out waiting for ${expression}`);
};

// Stand-in answers.
let briefPolls = 0;
let runPolls = 0;
let briefMode = "ok";
const now = new Date().toISOString();
function briefState() {
  briefPolls++;
  const status = briefPolls < 3 ? "queued" : "running";
  const brief = briefPolls < 3 ? null : briefPolls < 5 ? { status: "reading", pages_read: briefPolls - 2 } : { status: "writing", pages_read: 4 };
  return { run: { id: FAKE_BRIEF, url: "https://plausible.io/", status, brief, cost_usd: null, created_at: now, started_at: now, finished_at: null } };
}
function runState() {
  runPolls++;
  return {
    run: {
      id: FAKE_RUN, url: "https://plausible.io/", start_url: null, has_test_login: false, access_mode: "public", first_impression: null,
      entry: null, findings: null, verdict: null, run_facts: null, success_condition: null, retest_of: null, retest: null,
      brief_run_id: null, goal: "stand-in", status: runPolls < 3 ? "queued" : "running", outcome: null, reason: null,
      cost_usd: null, brain_model: null, created_at: now, started_at: null, finished_at: null,
    },
    steps: [], frictions: [],
  };
}
const posted = [];
handlers.push(async (msg) => {
  if (msg.method !== "Fetch.requestPaused") return;
  const { requestId, request } = msg.params;
  const url = new URL(request.url);
  const reply = (status, body) =>
    send("Fetch.fulfillRequest", {
      requestId, responseCode: status,
      responseHeaders: [{ name: "Content-Type", value: "application/json" }],
      body: Buffer.from(JSON.stringify(body)).toString("base64"),
    });
  if (request.method === "POST" && url.pathname === "/api/briefs") {
    posted.push({ path: url.pathname, body: JSON.parse(request.postData ?? "{}") });
    await sleep(400); // a realistic server answer
    if (briefMode === "rate") {
      return reply(429, { error: "rate_limited", message: "You've used 5 of 5 runs this hour, so you have 0 left. You can start another in about 25 minutes.", limit: 5, remaining: 0 });
    }
    return reply(201, { id: FAKE_BRIEF });
  }
  if (request.method === "POST" && url.pathname === "/api/runs") {
    posted.push({ path: url.pathname, body: JSON.parse(request.postData ?? "{}") });
    await sleep(400);
    return reply(201, { id: FAKE_RUN });
  }
  if (url.pathname === `/api/briefs/${FAKE_BRIEF}`) return reply(200, briefState());
  if (url.pathname.startsWith(`/api/briefs/${FAKE_BRIEF}/`)) return reply(200, { runs: [] });
  if (url.pathname === `/api/runs/${FAKE_RUN}`) return reply(200, runState());
  return send("Fetch.continueRequest", { requestId });
});

await send("Page.enable");
await send("Runtime.enable");
await send("Fetch.enable", { patterns: [{ urlPattern: "*/api/*" }] });

const results = {};
for (const width of [390, 1280]) {
  const r = (results[width] = {});
  briefPolls = 0;
  runPolls = 0;
  await send("Emulation.setDeviceMetricsOverride", { width, height: width === 390 ? 844 : 900, deviceScaleFactor: 1, mobile: width === 390 });
  await send("Network.clearBrowserCache").catch(() => {});

  // 0. Rate limit on Understand: a clear message, the button free again.
  await send("Page.navigate", { url: `${BASE}/?mode=understand#fu-form` });
  await waitFor(`document.querySelector('#fu-url') && document.readyState === 'complete'`);
  await sleep(800);
  r.understandTabOnLanding = await evaluate(`document.querySelector('#tab-understand')?.getAttribute('aria-selected')`);
  briefMode = "rate";
  await evaluate(`(() => { const i = document.querySelector('#fu-url'); const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set; set.call(i, 'plausible.io'); i.dispatchEvent(new Event('input', { bubbles: true })); })()`);
  await evaluate(`document.querySelector('#fu-form-panel button[type=submit]').click()`);
  await sleep(100);
  r.sendingShownAt100ms = await evaluate(`(() => { const p = document.querySelector('#fu-sending'); return p && !p.hidden ? p.textContent : null })()`);
  r.buttonAt100ms = await evaluate(`document.querySelector('#fu-form-panel button[type=submit]').textContent`);
  await waitFor(`!!document.querySelector('.fu-alert')`);
  r.rateLimitAlert = await evaluate(`document.querySelector('.fu-alert').innerText`);
  r.buttonAfterError = await evaluate(`[document.querySelector('#fu-form-panel button[type=submit]').textContent, document.querySelector('#fu-form-panel button[type=submit]').disabled]`);
  await shot(`${width}-0-rate-limited`);

  // 1. Understand submit -> brief waiting page.
  briefMode = "ok";
  const t0 = Date.now();
  await evaluate(`document.querySelector('#fu-form-panel button[type=submit]').click()`);
  await waitFor(`location.pathname === '/brief/${FAKE_BRIEF}'`);
  r.briefUrlAfterMs = Date.now() - t0;
  await waitFor(`document.body.innerText.includes('Writing your brief')`);
  r.briefWaitingAfterMs = Date.now() - t0;
  r.briefWaitingFirst = await evaluate(`document.querySelector('main').innerText.slice(0, 400)`);
  await shot(`${width}-1-brief-queued`);
  await waitFor(`document.body.innerText.includes('pages read') || document.body.innerText.includes('page read')`, 20000);
  r.briefReading = await evaluate(`document.querySelector('[aria-current=step]')?.innerText`);
  await shot(`${width}-2-brief-reading`);
  await waitFor(`document.querySelector('[aria-current=step]')?.innerText.includes('Writing the brief')`, 20000);
  await shot(`${width}-3-brief-writing`);
  r.overflowX = await evaluate(`document.documentElement.scrollWidth > innerWidth`);

  // 2. A draft from an earlier test of another site, then the real brief and "Test this journey".
  await evaluate(`sessionStorage.setItem('fu-test-draft', JSON.stringify({ goal: 'GOAL A from site X', success: 'SUCCESS A', access: 'account' }))`);
  await send("Page.navigate", { url: `${BASE}/brief/${REAL_BRIEF}` });
  await waitFor(`[...document.querySelectorAll('a')].some(a => a.textContent.includes('Test this journey'))`, 20000);
  const journey = await evaluate(`(() => { const card = [...document.querySelectorAll('a')].find(a => a.textContent.includes('Test this journey')).closest('li'); return { goal: card.querySelectorAll('textarea')[0].value, success: card.querySelectorAll('textarea')[1].value } })()`);
  r.journeyPicked = journey;
  await evaluate(`[...document.querySelectorAll('a')].find(a => a.textContent.includes('Test this journey')).click()`);
  await waitFor(`location.pathname === '/' && document.querySelector('#fu-goal')?.value === ${JSON.stringify(journey.goal.trim())}`, 20000);
  await sleep(1500); // the smooth scroll
  r.form = await evaluate(`({
    url: document.querySelector('#fu-url').value,
    goal: document.querySelector('#fu-goal').value,
    success: document.querySelector('#fu-success').value,
    access: document.querySelector('input[name=access]:checked')?.value,
    draft: sessionStorage.getItem('fu-test-draft'),
    formTop: Math.round(document.querySelector('#fu-form').getBoundingClientRect().top),
    viewport: innerHeight,
    focused: document.activeElement?.name || document.activeElement?.id || document.activeElement?.tagName,
    hash: location.hash,
  })`);
  await shot(`${width}-4-form-prefilled`);

  // 3. Submit the test -> run waiting page.
  await evaluate(`document.querySelector('input[name=permission]').click()`);
  const t1 = Date.now();
  await evaluate(`document.querySelector('#fu-form-panel button[type=submit]').click()`);
  await sleep(100);
  r.testSendingAt100ms = await evaluate(`(() => { const p = document.querySelector('#fu-sending'); return p && !p.hidden ? p.textContent : null })()`);
  await waitFor(`location.pathname === '/run/${FAKE_RUN}'`);
  r.runUrlAfterMs = Date.now() - t1;
  await waitFor(`document.body.innerText.includes('Run 66666666')`);
  r.runWaitingAfterMs = Date.now() - t1;
  r.runWaitingFirst = await evaluate(`document.querySelector('main').innerText.slice(0, 300)`);
  await shot(`${width}-5-run-queued`);
  await waitFor(`document.body.innerText.includes('RUNNING') || document.body.innerText.includes('Running')`, 20000);
  await shot(`${width}-6-run-running`);
  r.runOverflowX = await evaluate(`document.documentElement.scrollWidth > innerWidth`);
}
results.posted = posted.map((p) => ({ path: p.path, url: p.body.url, goal: p.body.goal, successCondition: p.body.successCondition, briefId: p.body.briefId }));
fs.writeFileSync(path.join(OUT, "results.json"), JSON.stringify(results, null, 2));
console.log(JSON.stringify(results, null, 2));
ws.close();
chrome.kill();
process.exit(0);

