  await send("Emulation.setDeviceMetricsOverride", { width, height: 900, deviceScaleFactor: 1, mobile: width < 600 });
  await send("Page.navigate", { url: "http://localhost:3124/about" });
  await sleep(1500);
  await ev(`localStorage.setItem('fu_theme','${theme}'); location.reload()`);
  await sleep(2000);
  await ev(`document.getElementById('who-built-this').scrollIntoView({block:'start'}); window.scrollBy(0,-90)`);
  await sleep(1200);
  const info = await ev(`({ overflow: document.documentElement.scrollWidth > innerWidth, img: (() => { const i = document.querySelector('img[alt="Divyanshu Verma (DV)"]'); return i && [i.complete, i.naturalWidth, Math.round(i.getBoundingClientRect().width)] })(), link: (() => { const a = [...document.querySelectorAll('a')].find(a => a.textContent.trim() === 'on X'); return a && [a.href, a.target, a.rel] })() })`);
  console.log(width, theme, JSON.stringify(info));
  const { data } = await send("Page.captureScreenshot", { format: "png" });
  fs.writeFileSync(`${out}/about-${width}-${theme}.png`, Buffer.from(data, "base64"));
}
ws.close(); chrome.kill(); process.exit(0);
